library(data.table)
base <- "/data/y01014/diliyaer/BLCA_CAF_project/GDF15_CAF_project"
out <- file.path(base,"analysis_revisions_20260906/CCDC80_robustness_audit")
dir.create(out,recursive=TRUE,showWarnings=FALSE)
g1 <- fread(file.path(base,"analysis_revisions_20260906/GSE293189_patient_level_CCDC80_TME/GSE293189_cell_level_scores.csv"))
g2 <- fread(file.path(base,"analysis_revisions_20260906/GSE135337_patient_level_CCDC80_TME/GSE135337_cell_level_scores.csv"))
g1 <- g1[tissue=="Tumor"]; g1[,CAF_ind:=label=="CAF"]; g1[,Myeloid_ind:=label=="Myeloid"]; g1[,T_ind:=label%in%c("Tcell","NK")]; g1[,Mixed:=CAF_ind&(Myeloid_score>0.25|Tcell_score>0.25|NK_score>0.25)]; g1[,CAF_clean:=CAF_ind&!Mixed]; g1[,cohort:="GSE293189"]
g2[,CAF_ind:=CAF_score>0.25&CAF_score>Myeloid_score&CAF_score>Tcell_score&CAF_score>NK_score]; g2[,Myeloid_ind:=Myeloid_score>0.25&Myeloid_score>CAF_score&Myeloid_score>Tcell_score&Myeloid_score>NK_score]; g2[,T_ind:=Tcell_score>0.25&Tcell_score>=CAF_score&Tcell_score>=Myeloid_score]; g2[,Mixed:=CAF_ind&(Myeloid_score>0.25|Tcell_score>0.25|NK_score>0.25)]; g2[,CAF_clean:=CAF_ind&!Mixed]; g2[,cohort:="GSE135337"]
summ <- function(d) d[,.(n_cells=.N,n_CAF=sum(CAF_clean),n_CAF_loose=sum(CAF_ind),n_Myeloid=sum(Myeloid_ind),n_T=sum(T_ind),CAF_fraction=mean(CAF_clean),Myeloid_fraction=mean(Myeloid_ind),CAF_CCDC80_mean=mean(CCDC80[CAF_clean],na.rm=TRUE),CAF_CCDC80_detected=mean(CCDC80[CAF_clean]>0,na.rm=TRUE),Myeloid_score_mean=mean(Myeloid_score[Myeloid_ind],na.rm=TRUE)),by=.(cohort,patient_id)]
p <- rbindlist(list(summ(g1),summ(g2)),fill=TRUE)[is.finite(CAF_CCDC80_mean)&n_CAF>=10]; p[,CCDC80_z:=as.numeric(scale(CAF_CCDC80_mean)),by=cohort]; p[,CCDC80_high:=CCDC80_z>=0]; fwrite(p,file.path(out,"robust_patient_level_metrics.csv"))
vars <- c("Myeloid_fraction","n_Myeloid","Myeloid_score_mean")
corfun <- function(d,v){ok<-is.finite(d$CAF_CCDC80_mean)&is.finite(d[[v]]);if(sum(ok)<4)return(data.table(n=sum(ok),rho=NA_real_,p=NA_real_));tt<-suppressWarnings(cor.test(d$CAF_CCDC80_mean[ok],d[[v]][ok],method="spearman",exact=FALSE));data.table(n=sum(ok),rho=unname(tt$estimate),p=tt$p.value)}
within <- rbindlist(lapply(vars,function(v) rbindlist(lapply(unique(p$cohort),function(cc){x<-corfun(p[cohort==cc],v);x[,`:=`(cohort=cc,variable=v)];x})))); within[,FDR:=p.adjust(p,"BH")]
pooled <- rbindlist(lapply(vars,function(v){ok<-is.finite(p$CCDC80_z)&is.finite(p[[v]]);d<-p[ok];fit<-lm(as.formula(paste(v,"~CCDC80_z+cohort")),data=d);data.table(variable=v,n=nrow(d),beta=coef(fit)["CCDC80_z"],p=coef(summary(fit))["CCDC80_z","Pr(>|t|)"],rho=cor(d$CCDC80_z,d[[v]],method="spearman"))})); pooled[,FDR:=p.adjust(p,"BH")]
loo <- rbindlist(lapply(vars,function(v) rbindlist(lapply(seq_len(nrow(p)),function(i){d<-p[-i];ok<-is.finite(d$CCDC80_z)&is.finite(d[[v]]);data.table(variable=v,omitted=p$patient_id[i],cohort=p$cohort[i],rho=if(sum(ok)>=5)cor(d$CCDC80_z[ok],d[[v]][ok],method="spearman") else NA_real_)}))))
fwrite(within,file.path(out,"within_cohort_robust_correlations.csv")); fwrite(pooled,file.path(out,"pooled_robust_regression.csv")); fwrite(loo,file.path(out,"leave_one_patient_out_correlations.csv")); fwrite(p[,.(n_patients=.N,n_CAF=sum(n_CAF),n_Myeloid=sum(n_Myeloid)),by=cohort],file.path(out,"robustness_audit.csv")); writeLines(c("Independent CAF robustness audit","GSE293189 tumor only; mixed CAF-like cells excluded","GSE135337 stricter CAF module threshold; mixed cells excluded","Patient-level continuous CCDC80 and leave-one-patient-out analyses"),file.path(out,"RUN_STATUS.txt"))
